\begin{equation}\tag{$\mathcal P$} \label{pb:compositepb}
    \min_{x\in\mathbb R^n} F(x) \triangleq f(x)+g(x)
\end{equation}

\revise{In the rest of the paper, $\M$ denotes a submanifold of $\bbR^{n}$ or $\bbR^{m \times n}$.}


A subset $\M$ of $\RR^n$ is said to be a \emph{$p$-dimensional $\C^2$-submanifold} of $\RR^n$ around $\bar{x} \in \M$ if there exists %
$\C^2$ function $\varphi : \RR^p \to \RR^n$ such that $\varphi$ \revise{maps} a neighborhood of $0 \in \RR^p$ \revise{to} a neighborhood of $\bar{x} \in\M$, \revise{that admits a smooth (local) inverse,} and \revise{which derivative} at $\varphi^{-1}(\bar{x})=0$ is injective.
A $p$-dimensional $\C^2$-submanifold of $\RR^n$ can alternatively be defined via a local equation, that is, a $\C^2$ function $\Phi : \RR^n \to \RR^{n-p}$ with a surjective derivative at $\bar x \in \M$ that satisfies for all $x$ close enough to $\bar x$: $x \in\M \Leftrightarrow \Phi(x) = 0$.


A basic tool to investigate approximations on manifolds is notion of the \emph{smooth curves}. A smooth curve on $\M$ is a $\C^2$ application $\gamma : I\subset \RR \to \M\subset \RR^n$, where $I$ is an open interval containing $0$. At each point $x\in\M$, the \emph{tangent space}, noted $\tangentM$, can be defined as the velocities of all smooth curves passing by $x$ at $0$:
\begin{equation*}
    \tangentM \triangleq \left\{ \smoothcurve'(0) ~|~ \smoothcurve : I \to \M \text{ is a smooth curve around $0$ and } \smoothcurve(0)=x \right\}.
\end{equation*}
The tangent space is a $p$-dimensional %
space containing \emph{tangent vectors}. Each tangent space $\tangentM$ is equipped with a scalar product $\langle\cdot, \cdot\rangle_x : \tangentM\times\tangentM\to\RR$, and the associated norm $\|\cdot\|_x$. In many cases, the tangent metric varies smoothly with $x$, making the manifold \emph{Riemannian}. In this paper, we use the ambient space scalar product to define the scalar product on tangent spaces; we will thus drop the subscript in the tangent scalar product and norm notations when there is no confusion possible. Related to the tangent space, we will also consider the \emph{normal space} $\normalM$ at $x\in\M$, defined as the orthogonal space to $\tangentM $ in $\RR^n$, and the \emph{tangent bundle manifold} defined by:
\[
\tangentBundle \triangleq \bigcup_{x\in\M}(x,\tangentM).
\]
Note also that both tangent and normal spaces at $x\in\M$  admit explicit expressions from derivatives of local parametrization $\varphi$ or local equations $\Phi$ defining $\M$:
\begin{equation*}
    \tangentM = \text{Im}~ \D_\varphi (0) = \text{Ker}~ \D_\Phi (x) \qquad \normalM = \text{Ker}~ \D_\varphi (0)^* = \text{Im}~ \D_\Phi (x)^*
\end{equation*}

A \emph{metric} on $\M$ can be defined as the minimal length over all curves joining two points $x, y\in\M$, ie. $\distM(x, y) = \inf_{\smoothcurve \in C_{x,y}}  \int_0^1 \|\smoothcurve'(t)\|_{\smoothcurve(t)} \mathrm{d}t$, where $C_{x,y}$ is the set of $[0, 1]\to\M$ smooth curves $\smoothcurve$ such that $\smoothcurve(0)=x$, $\smoothcurve(1)=y$. The minimizing curves generalize the notion of straight line between two points to manifolds. The constant speed parametrization of any minimizing curve is called a \emph{geodesic}.


Let $\funman:\M\to\RR$, the \emph{Riemannian differential} of $\funman$ at\;$x$ is the linear operator $\D \funman(x):\tangentM\to\RR$ defined by $\D \funman(x)[\eta]\triangleq\left. \frac{\mathrm{d}}{\mathrm{d}t}\funman\circ \smoothcurve(t) \right|_{t=0}$, where $\smoothcurve$ is a smooth curve such that $\smoothcurve(0)=x$ and $\smoothcurve'(0)=\eta$. In turn, the \emph{Riemannian gradient} $\grad \funman(x)$ is the unique vector of $\tangentM$ such that, for any tangent vector\;$\eta$, $\D \funman(x)[\eta] = \langle \grad \funman(x), \eta \rangle$.
If $\grad \funman(x)$ exists, a first order Taylor development can be formulated. Let $x\in\M$, $\eta\in\tangentM$ and $\smoothcurve$ denote a smooth curve passing by $x$, with velocity $\eta$ at $0$; then, for $t$ near $0$,
\begin{equation*}\label{eq:manifoldFirstOrderDevSmoothCurve}
    \funman\circ \smoothcurve(t) = \funman(x) + t \langle \grad \funman(x), \eta \rangle + o(t).
\end{equation*}

Notions of derivation for vector fields and of acceleration for curves are used to define second-order objects. Let a curve $\smoothcurve:I\to\M$ and a smooth vector field $Z$ on $\smoothcurve$, ie.\;a smooth map such that $Z(t)\in\tangentM[c(t)]$ for $t\in I$. The \emph{covariant derivative} of $Z$ on the curve $\smoothcurve$, denoted $\frac{\D}{\mathrm{d}t}Z:I\to\tangentBundle$, is defined by $\frac{\D}{\mathrm{d}t}Z(t) \triangleq \proj_{\smoothcurve(t)} Z'(t)$, where $Z'(t)$ denotes the derivative in the ambient space $\bbR^n$ and $\proj_{x}$ corresponds to the orthogonal projector from $\RR^n$ to $\tangentM$. The \emph{acceleration} of a curve $\smoothcurve$ is defined as the covariant derivative of its velocity: $\smoothcurve''(t) \triangleq \frac{\D}{\mathrm{d}t}\smoothcurve'(0)$. 

The \emph{Riemannian Hessian}  of $\funman$ at $x$ along $\eta$ is the linear operator $\Hess \funman(x):\tangentM\to\tangentM$ defined by the relation $\Hess \funman(x)[\eta] \triangleq \left. \frac{\D}{\mathrm{d}t} \grad \funman(\smoothcurve(t)) \right|_{t=0}$, where $\smoothcurve$ is a smooth curve such that $\smoothcurve(0)=x$, $\smoothcurve'(0)=\eta$. 
Equivalently, we have
$\langle\Hess \funman(x)[\eta], \eta\rangle = \left. \frac{\mathrm{d}^2}{\mathrm{d}t^2}\funman\circ \geocurve(t) \right|_{t=0}$, where $\geocurve$ is a geodesic such that $\geocurve(0)=x$, $\gamma'(0) = \eta$.
A second order Taylor development can now be formulated. Let $x\in\M$, $\eta\in\tangentM$, and $\smoothcurve$ be a smooth curve such that $\smoothcurve(0)=x$, $\smoothcurve'(0)=\eta$. Then, for $t$ near $0$,
\begin{equation*}%
    \funman\!\circ\!\smoothcurve(t) = \funman(x) \!+ t \langle \grad \funman(x), \eta \rangle + \frac{t^2}{2}\!(\langle \Hess \funman(x)[\eta], \eta \rangle\!+\!\langle \grad \funman(x), c''(0)\rangle)+ o(t^2).
\end{equation*}


\noindent\textbf{Algorithms on manifolds: retractions and convergence rates.}
Iterative Riemannian methods require a way to produce curves on $\M$ given a point $x$ and a tangent vector $\eta$. A geodesic curve passing at $(x, \eta)$, while attractive as the generalization of the straight line, has a prohibitive computational cost. We thus \emph{retractions}, i.e. approximations of it, defined on a manifold $\M$ as a smooth map $\R : \tangentBundle \to \M$ such that
\[%
    \text{$\R_x (0) = x\quad$ and $\quad \D\R_x (0) : \tangentM \to\tangentM$ is the identity map: $D\R_x (0 )[v] = v$,}
\]%
where, for each $x \in\M$, $\R_x : \tangentM\to\M$ is defined as the restriction of $\R$ at $x$, so that $\R_x(v) = \R(x, v)$. A \emph{second-order retraction} is a retraction $\R$ such that, for all $(x, \eta)\in\tangentBundle$, the curve $c(t)=\R_x(t\eta)$ has zero acceleration at 0: $c''(0)=0$.
Thus $t\mapsto\R_x(t\eta)$ is a practical curve passing by $(x, \eta)$ at $0$, and provides a similar development as above: %
for $t$ near 0,
\begin{equation}\label{eq:manifoldSecondOrderDevSecRetraction}
    \funman\circ\R_x(t \eta) = \funman(x) + t \langle \grad \funman(x), \eta\rangle + \frac{t^2}{2}\langle \Hess \funman(x)[\eta], \eta\rangle + o(t^2 \|\eta\|^2).
\end{equation}


Finally, the convergence rates on manifolds are defined as follows. A sequence of points $(x_k)$ \emph{converges (Q-)linearly} to some point $\bar{x}\in\M$ if there exist an integer $K>0$ and a constant $q\in(0,1)$ such that, for all $k\ge K$, there holds
\begin{equation*}
    \distM(x_{k+1}, \bar{x})\le q~ \distM(x_{k}, \bar{x}).
\end{equation*}
The sequence \emph{converges with order at least $p$} if there exists an integer $K>0$ and a constant $q\in(0,1)$ such that, for all $k\ge K$, there holds
\begin{equation*}
    \distM(x_{k+1}, \bar{x})\le q~\distM(x_{k}, \bar{x})^p.
\end{equation*}
The convergence is \emph{superlinear} when $p>1$ and \emph{quadratic} when $p=2$.


Consider a point $\bar{x}$ with $\funns(\bar{x})$ finite. The set of \emph{regular subgradients} %
\begin{equation*}
    \widehat\partial \funns(\bar{x}) \triangleq \left\{ v : \funns(x) \ge \funns(\bar{x}) + \langle v, x-\bar{x} \rangle + o(\|x-\bar{x}\|) \text{ for all } x\in\bbR^n \right\}
\end{equation*}
is closed and convex, but the subdifferential mapping $\widehat\partial \funns(\cdot)$ may not be outer semi-continuous \cite[Th. 8.6, Prop. 8.7]{rockafellar2009variational}. To overcome this problem, the set of \emph{(general or limiting) subgradients} is defined as
\begin{equation*}
    \partial \funns(\bar{x}) \triangleq \left\{ \lim_r v_r : v_r\in\widehat\partial \funns(x_r), x_r\to\bar{x}, \funns(x_r)\to \funns(\bar{x}) \right\}.
\end{equation*}
The limiting subdifferential is by design outer semi-continuous:
\[
\limsup_{x\to\bar{x}} \partial \funns (x) = \{u : \exists x_r\to\bar{x}, \exists u_r \to u \text{ with } u_r\in  \partial \funns (x_r) \} ~\subset~ \partial \funns (\bar{x}),
\]
which is an attractive property to study the properties of sequences of points whose subgradients converge.
We say that a function is \emph{(Clarke) regular} at $\bar{x}$ if the regular and limiting subdifferentials at $\bar{x}$ coincide \cite[Def. 7.25, Cor. 8.11]{rockafellar2009variational}. This is notably the case for convex functions where the two above definitions coincide with the convex subdifferential \cite[Prop. 8.12]{rockafellar2009variational}.


The subdifferential allows to derive optimality conditions: for a local minimizer $\bar x$ of $F$, we have $0\in \partial F(\bar x)$. For the objective function of \eqref{pb:compositepb}, this writes
\[
0\in \nabla f (\bar x) + \partial g(\bar x) \qquad\text{or equivalently}\qquad -\nabla f (\bar x) \in \partial g(\bar x).
\]
A point satisfying these conditions is called a critical point. The analysis of the algorithms of this paper will provide convergence guarantees towards critical points. %


A central tool to tackle non-differentiable functions is the \emph{proximity operator}.
For\;$\gamma\!>\!0$ and a function $\funns$; it is defined as the set-valued mapping
\begin{equation*}
    \prox_{\gamma \funns}(y) \triangleq \argmin_{u\in\bbR^n} \left\{ \funns(u) + \frac{1}{2\gamma}\|u-y\|^2\right\}.
\end{equation*}


A function $\funns$ is \emph{prox-regular} at a point $\bar{x}$ for a subgradient $\bar{v} \in \partial \funns(\bar{x})$ if $\funns$ is finite, locally lower semi-continuous at $\bar{x}$, and there exists $r>0$ and $\varepsilon>0$ such~that
$%
    \funns(x') \ge \funns(x) + \langle v, x'-x\rangle - \frac{r}{2}\|x'-x\|^2
$ %
whenever $v \in \partial \funns(x)$, $\|x-\bar{x}\|<\varepsilon$, $\|x'-\bar{x}\|<\varepsilon$, $\|v-\bar{v}\|<\varepsilon$ and $\funns(x)<\funns(\bar{x})+\varepsilon$.
When this holds for all $\bar{v} \in\partial \funns(\bar{x})$, we say that $\funns$ is prox-regular at $\bar{x}$ \cite[Def. 13.27]{rockafellar2009variational}.


\begin{assumption}\label{asm:fun}
    The functions $f$ and $g$ are proper and 
    \begin{itemize}
        \item[i)] $f$ is $\C^2(\bbR^n)$ with an $L$-Lipschitz continuous gradient;
        \item[ii)] $g$ is lower semi-continuous;
        \item[iii)] $\prox_{\gamma g}$ is non-empty on $\mathbb R^n$ for any $\gamma>0$;
        \item[iv)] $F(x) = f(x) + g(x)$ is bounded below.
    \end{itemize}
\end{assumption}

\begin{algorithm}
    \caption{General structure exploiting algorithm\label{alg:generic}}
    \begin{algorithmic}[1]
        \Require \revise{Pick $x_{0}$ arbitrary, $\gamma < 1 / L$.}
        \Repeat
        \State Compute $x_{k}\in\prox_{\gamma g}(y_{k-1} - \gamma \nabla f(y_{k-1}))$ and get $\M_{k}\ni x_{k}$ %
        \State Update $y_{k} = \manupdate_{\M_{k}} (x_{k})$ on the current manifold %
        \Until{stopping criterion}
    \end{algorithmic}
\end{algorithm}

\begin{definition}[partial smoothness]
    A function $g$ is ($\C^2$-)\emph{partly smooth} at a point $\bar{x}$ relative to a set $\M$ containing $\bar{x}$ if $\M$ is a $\C^2$ manifold around $\bar{x}$ and:
    \begin{itemize}
        \item (smoothness) the restriction of $g$ to $\M$ is a $\C^2$ function near $\bar{x}$;
        \item (regularity) $g$ is (Clarke) regular at all points $x\in\M$ near $\bar{x}$, with $\partial g(x)\neq\emptyset$;
        \item (sharpness) the affine span of $\partial g(\bar{x})$ is a translate of $\normalM[\bar{x}]$;
        \item (sub-continuity) the set-valued mapping $\partial g$ restricted to $\M$ is continuous at $\bar{x}$.
    \end{itemize}
\end{definition}

\begin{definition}\label{def:structqual}
   A point $\bar{x}$ of a $C^2$ submanifold $\M$ is a $r$-\emph{structured critical} point for $(f,g)$~if we have:
    \begin{itemize}
        \item[i)] proximal gradient stability: $\bar{x} = \prox_{g/r}(\bar{x}-1/r \nabla f( \bar{x} ) )$ ;
        \item[ii)] qualification condition: $0 \in \ri (\nabla f + \partial g)(\bar{x})$;
        \item[iii)] prox-regularity: $g$ is $r$-prox-regular at $\bar{x}$;
        \item[iv)] partial smoothness: $g$ is partly-smooth at $\bar{x}$ with respect to $\M$.
    \end{itemize}
\end{definition}

Standing at point $x\in\M$ with a proposed direction $\eta\in\tangentM$, a stepsize $\alpha>0$ is \emph{acceptable} \revise{if} it satisfies the following \emph{Armijo} condition %
\begin{equation}\label{eq:Armijo}
    \funtot(\R_x(\alpha \eta)) \le \funtot(x) + m_1 \alpha \langle \grad \funtot(x), \eta\rangle, \qquad\text{for $0 < m_1 < 1/2$.}
\end{equation}

The line search employs a second-order retraction $\R_x$, \revisebis{e.g.\;the exponential map, a projection retraction \cite{Absil2012ProjectionlikeRO}, or any other second-order retraction \cite{boumal2022intromanifolds}.\footnote{\revisebis{Indeed, in many applications of Riemannian optimization, computing geodesics and the exponential map can be costly and then retractions provide an efficient alternative. For this reason, we consider here second-order retractions \cite{absil2009optimization,boumal2022intromanifolds}.}}} %


In the following, we will consider a \emph{backtracking} \revise{line search} for finding an acceptable stepsize $\alpha$: the unit stepsize is first tried, and then the search space is reduced geometrically. %
In practice, we use exactly \cite[Alg. A6.3.1]{dennis1996numerical}, which features polynomial interpolation of $\funman$ in the search space.


\begin{algorithm}
    \caption{$\manupdate$-Newton\label{alg:ManUpNewton}}
    \begin{algorithmic}[1]
        \Require Manifold $\M$, point $x\in\M$
        \State Find $d$ in $\tangentM$ that solves
        \begin{equation*}\tag{Newton equation}\label{eq:Newtoneq}
            \grad F(x) + \Hess F(x)[d] = 0
        \end{equation*}
        \State Find $\alpha$ satisfying the Armijo condition \eqref{eq:Armijo} with direction $d$
        \State \Return $y = R_x(\alpha d)$
    \end{algorithmic}
\end{algorithm}

