\begin{theorem}\label{th:Newton}
    Let \cref{asm:fun} hold and take $\gamma\in(0, 1/L)$. Consider the sequence of iterates $(x_k)$ generated by \cref{alg:generic} equipped with the Riemannian Newton manifold update (\cref{alg:ManUpNewton}). If $~ \Hess \funtot(x_k)$ is positive definite at each step, then all limit points of $(x_k)$ are critical points of $\funtot$ and share the same functional value.

    Furthermore, assume that the sequence $(y_k)$ admits %
    a limit point $x^\star$ such\;that
    \begin{itemize}
        \item[i)] $x^\star\in\M$ is a $r$-structured critical point for $(f,g)$  with $r<1/\gamma$;
        \item[ii)] $\Hess_{\M} \funtot(x^\star)\succ 0$ and  $\Hess_{\M} \funtot$ is locally Lipschitz around $x^\star$.
    \end{itemize}
    Then, after some finite time,
    \begin{itemize}
        \item[a)] the sequence $(x_k)$ lies on $\M$;
        \item[b)] $x_k$ converges to $x^\star$ quadratically{: for large $k$, there exists $c>0$ such that}
            \begin{equation*}
                \distM(x_{k+1}, x^\star) \le {c ~} \distM(x_k, x^\star)^2.
            \end{equation*}
    \end{itemize}
\end{theorem}

