\begin{theorem}[Proximal gradient points smoothly locate manifolds] \label{th:PGpointlocatemanifolds}
    Let $f$ be a $\C^2$ function on $\RR^n$ and $g$ a lower semi-continuous function on $\RR^n$. Suppose that $g$ is both $r$-prox-regular at $\bar{x}$ and partly-smooth relative to $\M$ at $\bar{x}$.

    Take $\gamma$, $\bar \gamma$ such that $0<\gamma<\bar \gamma \leq 1/r$ and $\bar{x}=\prox_{\bar\gamma g}(\bar{y}-\bar\gamma \nabla f(\bar{y}))$. If
    \begin{itemize}
        \item[i)] $\frac{1}{\gamma}(\bar{y}-\bar{x}) - \nabla f(\bar{y})  \in \ri \partial g(\bar{x})$ ~\revise{(the relative interior of the subdifferential at $\bar{x}$)};
        \item[ii)] either a) $\gamma$ is sufficiently close to $\bar{\gamma}$, or b) $\bar{y}$ is sufficiently close to $\bar{x}$;
    \end{itemize}
    then, the proximal gradient $y \mapsto \prox_{\gamma g}(y - \gamma\nabla f(y))$ is $\C^{1}$ and $\M$-valued near $\bar{y}$.
\end{theorem}

\begin{proof}
    Adopting the same reasoning as in \cite[Sec. 5]{lewis2002active} and \cite[Sec. 4.1]{daniilidis2006geometrical}, we consider the function
    \begin{equation*}
        \begin{array}{rl}
            \rho : \bbR^n\times\bbR^n & \to \bbR                                                 \\
            (x, y)                    & \mapsto g(x)+\frac{1}{2\gamma}\|x-y+\gamma\nabla f(y)\|^2,
        \end{array}
    \end{equation*}
    and denote by $\rho_y = \rho(\cdot,y)$. Computing the proximal gradient $\prox_{\gamma g}(y-\gamma\nabla f(y))$ can then be seen as minimizing the parametrized function $\rho_y$.

    \noindent\underline{Step 1.} As a first step, we study the minimizers of $\rho_y$ restricted to $\M$, for $y$ near\;$\bar{y}$. %
    We consider the parametric manifold optimization problem, for $y$ near $\bar{y}$:
    \begin{equation}\tag{$ P_\M(y)$}
        \min_{x\in\M} \rho_y(x). \label{pb:pb_mancstr}
    \end{equation}
    Since $g$ is $\C^2$-partly-smooth relative to $\M$ and $f$ is $\C^2(\bbR^n)$, $\rho_y$ is twice continuously differentiable on $\M$. \revise{Moreover, the $r$-prox-regularity gives easily (see \cref{lemma:prox_strong_min}) that $\rho_{\bar{y}}$ is lower-bounded by $(\frac{1}{\gamma}-r)\|\cdot - \bar{x}\|^2/2$ on a neighborhood of $\bar x$ in $\bbR^n$ and, a fortiori, in $\M$. From usual rationale (see e.g.
    \cite[Chap 4.2, 6.1]{boumal2022intromanifolds}), this implies}
    \begin{equation*}
        \grad \rho_{\bar{y}}(\bar{x}) = 0 \qquad \Hess \rho_{\bar{y}}(\bar{x}) \succeq \Big(\frac{1}{\gamma}-r\Big) I \succ 0,
    \end{equation*}
    \revise{which are the conditions to apply the implicit functions theorem, as follows.}

    We consider the equation $\Phi(x, y) = 0$, for $x, y$ near $\bar{x}, \bar{y}$, where $\Phi:\M\times\bbR^n\to\tangentBundle$ is defined as $\Phi(x, y) = \grad \rho_y(x)$. This function is continuously differentiable on a neighborhood of $(\bar{x}, \bar{y})$, and its differential relative to $\bar x$ at that point, $\Hess \rho_{\bar{y}}(\bar{x})$, is invertible. The implicit function theorem thus grants the existence of neighborhoods $\N_{\bar{x}}$, $\N_{\bar{y}}$ of $\bar{x}$, $\bar{y}$ in $\M$, $\bbR^n$, and a continuously differentiable function $\hat{x}:\N_{\bar{y}} \to \N_{\bar{x}}$ such that, for any $y$ in $\N_{\bar{y}}$, $\Phi(\hat{x}(y), y) = \grad \rho_y(\hat{x}(y)) = 0$. Actually, $\hat{x}(y)$ is a strong minimizer of $\rho_y$ on $\M$ for $y$ close enough to $\bar{y}$. Indeed, the mapping $\hat{x}$ is continuous on $\N_{\bar{y}}$, so that $y \mapsto \Hess \rho_y(\hat{x}(y))$ is also continuous there and the property $\Hess \rho_{\bar{y}}(\hat{x}(\bar{y}))\succ 0$ extends locally around $\bar{y}$.

    \noindent\underline{Step 2.}  As a second step, we turn to show that the minimizer $\hat{x}(y)$ of $\rho_y$ on $\M$ is actually a strong critical point of $\rho_y$ in $\bbR^n$ \cite[Def. 5.3]{lewis2002active}, and thus the proximal gradient of point $y$. More precisely, we claim that, for $y$ near $\bar{y}$ and $x=\hat{x}(y)$, there holds $0\in\ri \partial \rho_y(x)$, that is
    \begin{equation*}
        \frac{1}{\gamma}(y-x) - \nabla f(y)  \in \ri \partial g(x).
    \end{equation*}

    This property holds at $(\bar{x}, \bar{y})$ by assumption. By contradiction, assume there exist sequences of points $(y_r)$ with limit $\bar{y}$, $(x_r) = (\hat x(y_r))$ with limit $\bar{x} = \hat x(\bar{y})$ and $(h_r)$ of unit norm $\|h_r\|=1$ such that for all $r$, $h_r$ separates 0 from $\partial \rho_{y_r}(x_r)$:
    \begin{equation*}
        \inf_{h\in\partial \rho_{y_r}(x_r)} \langle h_r, h\rangle \ge 0.
    \end{equation*}
    Since $(h_r)$ is bounded, a converging subsequence can be extracted from it, let $\bar{h}$ denote its limit. At the cost of renaming iterates, we assume that $\lim_{r\to\infty} h_r = \bar{h}$. The above property still holds at the limit $r\to\infty$. Indeed, let $\bar{u}\in\partial \rho_{\bar{y}}(\bar{x})$. Since $g$ is partly smooth, the mapping $(x, y)\in \N_{\bar{x}}\times\N_{\bar{y}} \mapsto\partial \rho_y(x) = \partial g(x) + \frac{1}{\gamma}(x-y)$ is continuous. Therefore, there exists a sequence $(u_r)$ such that $u_r\in\partial\rho_{y_r}(x_r)$ and $\lim_{r\to\infty} u_r=\bar{u}$. We have for all $r$: $\langle u_r, h_r\rangle \ge 0$, which yields at the limit $\langle\bar{u}, \bar{h}\rangle\ge 0$. Thus $\bar{h}$ separates $0$ from $\partial \rho_{\bar{y}}(\bar{x})$, which contradicts our assumption.

    \noindent\underline{Conclusion.} We thus have a continuously differentiable function $\hat{x}$ defined on a neighborhood of $\bar{y}$ such that i) $\hat{x}(\bar{y}) = \bar{x}$, ii) $\hat{x}(y)$ is a strong minimizer of $\rho_y$ on $\M$, iii) $0\in\ri\partial \rho_y(\hat{x}(y))$.

    This last point tells us that $(y-\hat x(y))/\gamma -\nabla f(y) \in \partial g(\hat x(y))$. The characterization of proximity by the optimality condition (\cref{th:proxex}) gives
that $\hat{x}(y)=\prox_{\gamma g}(y-\gamma \nabla f(y))$ for $y$ close enough to $\bar{y}$.
\end{proof}

\begin{theorem}%
    \label{th:identiflocalcv_sperlin}
    Let \cref{asm:fun} hold and take $\gamma\in(0, 1/L)$\revise{, where $L$ is the Lipschitz constant for $\nabla f$}. Assume that \cref{alg:generic} generates a sequence $(y_k)$ which admits at least one limit point $\bar{x}$ such that:
    \begin{itemize}
        \item[i)] $\bar{x}\in\M$ is a $r$-structured critical point for $(f,g)$ with $r<1/\gamma$;
        \item[ii)] $\manupdate_{\M}$ has superlinear convergence rate of order $1+\theta\in(1,2)$ %
        near $\bar{x}$ in $\M$.
    \end{itemize}
    Then, after some finite time:
    \begin{itemize}
        \item[a)] the full sequence $(x_k)$ lies on $\M$;
        \item[b)] $x_k$ converges to $\bar{x}$ superlinearly with the same order as $\manupdate$:
              \begin{equation}\label{eq:super}
                  \distM(x_{k+1},\bar{x}) \le c ~ \distM(x_k, \bar{x})^{1+\theta} \qquad \text{ for some $c>0$.}
              \end{equation}
    \end{itemize}
\end{theorem}

\begin{proof}
    Let us note $ \PGop(y) = \prox_{\gamma g}(y - \gamma \nabla f(y)) $ for $y\in\mathbb{R}^n$.
    The part i) of the assumptions enables us to show the existence of some neighborhood of $\bar{x}$ on which the proximal gradient operation is $\M$-valued and Lipschitz continuous. More precisely, 
    \cref{th:PGpointlocatemanifolds} 
    implies that there exists $\delta_1>0$ and $C>0$ such that, 
    \[%
      \PGop(y)\in\M \label{proof:inM} \quad \text{ and } \quad \|\PGop(y)- \PGop(\bar{x})\| \le C \|y-\bar{x}\| \qquad \text{for all $y$ in $\B(\bar{x}, \delta_1)$}.
    \]%
    Now, if $y$ belongs to $\M$, we get that there exists $\varepsilon_1>0$ such that for any $y$ in $\B_{\M}(\bar{x}, \varepsilon_1)$, $\PGop(y)\in\M$; but in addition, the Euclidean Lipschitz continuity can be translated into a Riemannian one (see \cref{lemma:Euclidean_to_Riemannian}) since   for some $\delta>0$,
    \begin{multline}\label{eq:EuctoRie}
        (1-\delta)\distM(\PGop(y), \bar{x}) = (1-\delta)\distM(\PGop(y), \PGop(\bar{x}))  \le \|\PGop(y)-\PGop(\bar{x})\| \\
        \le C \|y-\bar{x}\| \le C (1+\delta)\distM(y, \bar{x})
    \end{multline}
    Hence, there is $q_1>0$ such that for any $y$ in $\B_{\M}(\bar{x}, \varepsilon_1)$
    \begin{equation}\label{proof:PGopEstimate}
        \distM(\PGop(y), \bar{x}) =  \distM(\PGop(y), \PGop(\bar{x}))   \le  q_1 ~ \distM(y, \bar{x}).
    \end{equation}

    Then, the part ii) of the assumptions gives us the existence of $\varepsilon_2$, $q_2>0$ and $\theta\in(0,1)$ such that, for any $x$ in $\B_{\M}(\bar{x}, \varepsilon_2)$,
    \begin{equation}\label{proof:manupdateEstimate}
        \distM(\manupdate_{\M}(x), \bar{x}) \le q_2 ~ \distM(x, \bar{x})^{1+\theta}.
    \end{equation}
    Let us now take any $x\in\B_{\M}(\bar{x}, \varepsilon)$ where $\varepsilon=\min(\varepsilon_1,\varepsilon_2,(\varepsilon_1 / q_2)^{\frac{1}{1+\theta}},(q_2 q_1)^{-\frac{1}{\theta}})$: \\
    \noindent (\emph{i}) Since $x\in\B_{\M}(\bar{x}, \varepsilon_2)$, the manifold update \eqref{proof:manupdateEstimate} yields
    \begin{equation*}
        \distM(\manupdate_{\M}(x), \bar{x}) \le q_2 ~ \distM(x, \bar{x})^{1+\theta} \le q_2 ~ \varepsilon^{1+\theta} \le \varepsilon_1.
    \end{equation*}
    \noindent (\emph{ii}) As $\manupdate_{\M}(x)$ lies in $\B_{\M}(\bar{x}, \varepsilon_1)$, the proximal gradient update \eqref{proof:PGopEstimate} applied to $y = \manupdate_{\M}(x)$ gives
    \begin{multline}\label{eq:superlinear}
        \distM(\PGop(\manupdate_{\M}(x)), \bar{x}) \le    q_1 \distM(\manupdate_{\M}(x), \bar{x}) \\ \le q_1 q_2 ~ \distM(x, \bar{x})^{1+\theta} \le q_1 q_2 ~ \varepsilon^\theta \distM(x, \bar{x}).
    \end{multline}
    Since $q_2 q_1 \varepsilon^\theta \le 1$  by construction, this gives %
    \begin{equation}\label{eq:manstable}
        \distM(\PGop(\manupdate_{\M}(x)), \bar{x}) \le \distM(x, \bar{x}) \qquad \text{for any $x\in\B_{\M}(\bar{x}, \varepsilon)$}.
    \end{equation}
    We have thus proved the existence of a neighborhood $\B_\M(\bar{x}, \varepsilon)$ of $\bar{x}$ in $\M$ which is stable for an iteration of \cref{alg:generic} and over which one iteration has a superlinear improvement of order $1+\theta$ (by \eqref{eq:superlinear}).


    Finally, since $\bar{x}$ is a limit point of $(y_k)$, there exists $K<\infty$ such that $y_K\in\B(\bar{x},(1-\delta)\varepsilon/C)$. Besides, \eqref{eq:EuctoRie} tells us that $ \distM(\PGop(y_K), \bar{x})\le \varepsilon$ and thus $x_k$ and $y_k$ belong to $\B_{\M}(\bar{x}, \varepsilon)$ for all $k>K$ by \eqref{eq:manstable}. %
    We conclude that $x_{k+1}=\PGop(y_k)\in\M$ for all $k\geq K$, and, using \eqref{eq:superlinear}, that we have \eqref{eq:super} with $c= q_1 q_2$, for all $k>K$. 
\end{proof}

\begin{lemma}\label{lemma:LS_exists_valid_stepsizes}
    Let \cref{asm:fun} hold and consider a manifold $\M$ equipped with a retraction $\R$ and a pair $(x, \eta)\in\tangentBundle$. If $\funtot$ is differentiable on $\M$ at $x$, $\langle \grad \funtot (x), \eta\rangle <0$, and $m_1<1$, then there exists $\hat\alpha>0$ such that any step size $\alpha\in(0, \hat\alpha)$ is acceptable by the Armijo rule \eqref{eq:Armijo}.
\end{lemma}

\begin{proof}
    We adapt a part of the proof of  \cite[Th. 6.3.2]{dennis1996numerical} for the Armijo rule and the Riemannian setting. Since $m_1<1/2$, for any $\alpha$ sufficiently small there holds
    \begin{equation*}
        \funtot\circ \R_x(\alpha \eta) \le \funtot\circ\R_x(0) + m_1 \D\left(\funtot\circ\R_x \right)(0)[\alpha\eta] = \funtot(x) + m_1 \alpha \langle \grad \funtot(x), \eta\rangle.
    \end{equation*}
    Since $\funtot$ is bounded below, there exists a smallest $\hat{\alpha}$ such that $\funtot(\R_x(\hat\alpha \eta)) = \funtot(x) + m_1 \hat\alpha \langle \grad \funtot(x), \eta\rangle$. Thus all stepsizes in $(0, \hat\alpha)$ are acceptable by\;\eqref{eq:Armijo}.
\end{proof}

In addition, a \revise{line search} performed near a minimizer with a Newton direction
should accept the unit stepsize, so that a full step may be taken. This is the case when the Riemannian Hessian around this minimizer is positive definite as stated by the next lemma, \revise{which is a direct corollary of \cref{th:unitstepsuperlinearcv}.}
\begin{lemma}\label{lemma:LS_unit_stepsize}
    Let \cref{asm:fun} hold and consider a manifold $\M$ equipped with a retraction $\R$, a point $x^\star\in\M$ and a pair $(x, \eta)\in\tangentBundle$. Assume that $\funtot$ is twice differentiable on $\M$ near a strong local minimizer  $x^\star$  on $\M$, that is $\Hess \funman(x^\star)$ is positive definite.
    If the direction $\eta$ brings a superlinear improvement towards $x^\star$, that is $\distM(\R_x(\eta), x^\star) = o(\distM(x, x^\star))$ as $x\to x^\star$, and $0<m_1<1/2$, then $\eta$ is acceptable by the Armijo rule\;\eqref{eq:Armijo} with unit stepsize $\alpha=1$.
\end{lemma}

\begin{proof}
    As the Riemannian Hessian is assumed to be positive definite, Newton's direction is a descent direction:
    \begin{equation*}
        \langle \grad \funtot(x_k), d_k \rangle = -\langle \grad \funtot(x_k), \Hess \funtot(x_k)^{-1} \grad \funtot(x_k) \rangle < 0.
    \end{equation*}
    The Riemannian Newton manifold step is therefore well-defined, and the \revise{line search} terminates by \cref{lemma:LS_exists_valid_stepsizes}, so that the manifold update is well-defined and provides descent \revise{($F(y_{k})\le F(x_{k})$)}. 


    \revise{Now, since the proximal gradient update provides a descent (see \cite[Lem. 10.4]{beck2017first}),
    \begin{equation}\label{eq:proofglobalalg_descent}
        F(x_{k+1}) \le F(y_k) - \frac{1-\gamma L}{2\gamma} \| x_{k+1}-y_k \|^2 \le F(x_k) - \frac{1-\gamma L}{2\gamma} \| x_{k+1}-y_k \|^2.
    \end{equation}
    The sequence $(F(x_k))$ is thus non-increasing and lower-bounded, therefore it converges.
    Besides, any accumulation point of $(x_k)$ is a critical point of $F$. Indeed, summing equation \eqref{eq:proofglobalalg_descent} for $k=1, \ldots, n$ yields:
    \begin{equation*}
        \frac{1-\gamma L}{2\gamma} \sum_{k=1}^n \| x_{k+1}-y_k \|^2 \le F(x_1) - F(x_{n+1}) \le F(x_1)-\inf F < +\infty.
    \end{equation*}
    Since $ \dist (0, \partial F(x_{k+1})) \le \frac{L\gamma + 1}{\gamma}\|x_{k+1}-y_k\|$ (see e.g. the proof of\;\cite[Prop.\;13]{bolte2015error}), we have that 
    $\dist (0, \partial F(x_{k+1}))$
    converges to $0$. The outer-semi continuity of the limiting subdifferential then yields criticality of accumulation points.}





    Now we apply the local convergence of Riemannian Newton \cite[Th. 6.3.2]{absil2009optimization}:
    assumption ii) ensures that
    the Riemannian Newton direction $d$ computed in step\;1 of\;\cref{alg:ManUpNewton} provides a quadratic improvement %
    on a neighborhood of $x^\star$ on\;$\M$. Moreover, the \revise{line search} returns the unit-stepsize after some finite time: $\alpha=1$ is tried first, and is acceptable for directions providing superlinear improvement by \cref{lemma:LS_unit_stepsize}. Thus the whole Riemannian Newton update provides quadratic improvement after some finite time. Using this and assumption i), \cref{th:identiflocalcv_sperlin} applies and yields the results.
\end{proof}

\begin{lemma}
    \label{th:proxex}
    Consider a function $\funns:\bbR^n\to\bbR$, a pair of points $\bar{x}, \bar{y}$ and a \revise{step length} $\bar{\gamma}>0$ such that $\bar{x}=\prox_{\bar\gamma \funns}(\bar{y})$ and $\funns$ is $r$ prox-regular at $\bar{x}$ for subgradient $\bar{v} \triangleq (\bar{y}-\bar{x}) / \bar{\gamma}$.

    Then, for any $\gamma\in(0, \min(1/r, \bar\gamma))$, there exists a neighborhood $\N_{\bar{y}}$ of $\bar{y}$ over which $\prox_{\gamma \funns}$ is single-valued and $(1-\gamma r)^{-1}$-Lipschitz continuous. Furthermore, there holds
    \begin{equation*}
        x = \prox_{\gamma \funns}(y) \Leftrightarrow (y-x)/\gamma \in\partial \funns(x)
    \end{equation*}
    for $y\in\N_{\bar{y}}$ and $x$ near $\bar{x}$ in the sense $\|x-\bar{x}\|<\varepsilon$, $|\funns(x)-\funns(\bar{x})|<\varepsilon$ and $\|(y-x)/\gamma - \bar{v}\|<\varepsilon$. %
\end{lemma}

\begin{proof}
    One can easily check that prox-regularity of $\funns$ at $\bar{x}$ for subgradient $\bar{v}$ is equivalent to prox-regularity of function $\tilde{\funns}$ around $0$ for subgradient $0$, with $\tilde{\funns} = \funns(\cdot + \bar{x}) - \langle \bar{v}, \cdot\rangle - \funns(\bar{x})$ and a change of variable $\tilde{x} = x-\bar{x}$. Similarly, $\bar{x}=\prox_{\bar\gamma \funns}(\bar{y})$ is characterized by its global optimality~condition
    \begin{equation*}
        \funns(x) + \frac{1}{2\bar\gamma}\|x-\bar{y}\| > \funns(\bar{x}) + \frac{1}{2\bar\gamma}\|\bar{x}-\bar{y}\|^2 \qquad \text{ for all } x\neq\bar{x},
    \end{equation*}
    which we may write as
    \begin{equation*}
        \funns(x) > \funns(\bar{x}) + \langle \bar{v}, x-\bar{x} \rangle - \frac{1}{2\bar\gamma}\|x - \bar{x}\|^2 \qquad \text{ for all } x\neq\bar{x}.
    \end{equation*}
    Under that same change of variables, since $\tilde{\funns}(0) = 0$, this optimality condition rewrites as
    \begin{equation*}
        \tilde{\funns}(\tilde{x}) > - \frac{1}{2\bar\gamma}\|\tilde{x}\|^2 \qquad \text{ for all } \tilde{x}\neq 0.
    \end{equation*}
    We may thus apply Theorem 4.4 from \cite{poliquin1996prox} to get the claimed result on $\tilde{\funns}$, which transfers back to $\funns$ as our change of function and variable is bijective. We thus obtain that for $\gamma\in(0, \min(1/r, \bar\gamma))$, on a neighborhood $\N_{\bar{y}}$ of $\bar{y}$, $\prox_{\gamma \funns}$ is single-valued, $(1-\gamma r)^{-1}$-Lipschitz continuous and $\prox_{\gamma \funns}(y)=[I+\gamma T]^{-1}(y)$, where $T$ denotes the $\funns$-attentive $\varepsilon$-localization of $\partial \funns$ at $\bar{x}$. Taking $y$ near $\bar{y}$ and $x$ near $\bar{x}$ such that $\|x-\bar{x}\|<\varepsilon$, $|\funns(x)-\funns(\bar{x})|<\varepsilon$ and $\|(y-x)/\gamma - \bar{v}\|<\varepsilon$ allows to identify the localization of $\partial \funns(x)$ with $\partial \funns(x)$, so that
    \begin{equation*}
        \frac{y-x}{\gamma}\in \partial \funns(x)\Leftrightarrow \frac{y-x}{\gamma}\in T(x)\Leftrightarrow (I+\gamma T)(x)=y\Leftrightarrow x=\prox_{\gamma \funns}(y).
    \end{equation*}
    Note that the proof of \cite[Th. 4.4]{poliquin1996prox} includes a minor error relative to the Lipschitz constant computation, we report here a corrected value.
\end{proof}

\begin{lemma}\label{lemma:prox_strong_min}
    Let $f$ and $g$ denote two functions and $\bar{x}$, $\bar{y}$ two points such that $f$ is differentiable at $\bar{y}$ and $g$ is $r$-prox-regular at $\bar{x}$ for subgradient $\frac{1}{\gamma}(\bar{y}-\bar{x}) - \nabla f(\bar{y}) \in \partial g(\bar{x})$ with $\gamma \in (0, 1/r)$.
    Then, the function $\rho_{\bar{y}} : x\mapsto g(x) + \frac{1}{2\gamma}\|\bar{y}-\gamma\nabla f(\bar{y}) - x\|^2$ satisfies %
    \begin{equation*}
        \rho_{\bar{y}}(x) \ge \rho_{\bar{y}}(\bar{x}) + \frac{1}{2} \left( \frac{1}{\gamma} - r \right) \| x-\bar{x} \|^2, \qquad \text{for all $x$ near $\bar{x}$.}
    \end{equation*}
\end{lemma}

\begin{proof}
    Prox-regularity of $g$ at $\bar{x}$ with subgradient $\frac{1}{\gamma} (\bar{y}-\gamma \nabla f(\bar{y}) - \bar{x}) \in \partial g(\bar{x})$ writes
    \begin{equation*}
        g(x) \ge g(\bar{x}) + \frac{1}{\gamma}\langle \bar{y}-\gamma \nabla f(\bar{y}) - \bar{x} , x-\bar{x} \rangle - \frac{r}{2} \| x-\bar{x} \|^2.
    \end{equation*}
    The identity $ 2\langle b-a, c-a\rangle = \|b-a\|^2 + \|c-a\|^2 -   \|b-c\|^2 $ applied to the previous scalar product yields:
    \begin{equation*}
        g(x) \ge g(\bar{x}) + \frac{1}{2\gamma} \| \bar{y}-\gamma \nabla f(\bar{y}) - \bar{x} \|^2 + \frac{1}{2\gamma} \| x-\bar{x} \|^2 - \frac{1}{2\gamma} \|\bar{y}-\gamma \nabla f(\bar{y}) - x \|^2 - \frac{r}{2} \| x-\bar{x} \|^2,
    \end{equation*}
    which rewrites
    \begin{equation*}
        \underbrace{ g(x) + \frac{1}{2\gamma} \|\bar{y}-\gamma \nabla f(\bar{y}) - x \|^2 }_{=\rho_{\bar{y}}(x) } \ge  \underbrace{  g(\bar{x}) + \frac{1}{2\gamma} \| \bar{y}-\gamma \nabla f(\bar{y}) - \bar{x} \|^2   }_{=\rho_{\bar{y}}(\bar{x}) } + \frac{1}{2} \left( \frac{1}{\gamma} - r \right) \| x-\bar{x} \|^2,
    \end{equation*}
    \vspace*{-1ex}
which is the claimed inequality.
\end{proof}

\begin{lemma}\label{lem:InvRetractionApproxLog}
    Consider a point $\bar{x}$ of a Riemannian manifold $\M$, equipped with a retraction $\R$ such that $\R_{\bar{x}}$ is $\C^2$. For any $\varepsilon>0$, there exists a neighborhood $\U$ of $\bar{x}$ in $\M$ such that 
    \begin{equation*}
        (1-\varepsilon)\distM(x, \bar{x}) \le \|\R^{-1}_{\bar{x}}(x)\| \le (1+\varepsilon)\distM(x, \bar{x}) \qquad \text{ for all $x\in\U$.}
    \end{equation*}
    where $\R^{-1}_{\bar{x}}:\M\to\tangent{\bar{x}}{\M}$ is the smooth inverse of $\R_{\bar{x}}$ defined locally around $\bar{x}$.
\end{lemma}

\begin{proof}
    The retraction at $\bar{x}$ can be inverted locally around $0$. Indeed, as $\D\R_{\bar{x}}(0_{\tangent{\bar{x}}{\M}})=I$ is invertible and $\R_{\bar{x}}$ is $\C^2$, the implicit function theorem provides the existence of a $\C^2$ inverse function $\R^{-1}_{\bar{x}}:\M\to\tangent{\bar{x}}{\M}$ defined locally around $\bar{x}$. Furthermore, one shows by differentiating the relation $\R_{\bar{x}}\circ\R_{\bar{x}}^{-1}$ that the differential of $\R^{-1}_{\bar{x}}$ at $\bar{x}$ is the identity.

    We consider the function $f:\M\to\RR$ defined by $f(x)=\|\log_{\bar{x}}(x)\|-\|\R_{\bar{x}}^{-1}(x)\|$. Clearly $f(\bar{x})=0$, and $\D f(\bar{x})=0$ as the differentials of both $\R_{\bar{x}}^{-1}$ and logarithm at $\bar{x}$ are the identity. In local coordinates $\hat{x}=\log_{\bar{x}}{x}$ around $\bar{x}$, $f$ is represented by the function $\hat{f}=f\circ\exp_{\bar{x}}: \tangent{\bar{x}}{\M}\to\RR$. As $\hat{f}(\hat{\bar{x}})=0$, $\D \hat{f}(\hat{\bar{x}})=0$ and $\hat{f}$ is $\C^2$, there exists some $C>0$ such that
    \begin{equation*}
        -C \|\hat{x} - \hat{\bar{x}}\|^2 \le \hat{f}(\hat{x}) \le C \|\hat{x} - \hat{\bar{x}}\|^2 \qquad\text{in a neighborhood $\hat{\U}$ of $\hat{\bar{x}}$,}.
    \end{equation*}
    For any $\varepsilon>0$, by taking a small enough neighborhood $\hat{\U}'\subset\hat{\U}$, there holds
    \begin{equation*}
        -\varepsilon \|\hat{x} - \hat{\bar{x}}\| \le \hat{f}(\hat{x}) \le \varepsilon \|\hat{x} - \hat{\bar{x}}\|.
    \end{equation*}
    Thus for all $x$ in $\U = \R_{\bar{x}}(\hat{\U}')$,
    \begin{equation*}
        -\varepsilon \|\log_{\bar{x}}(x)\| \le \|\log_{\bar{x}}(x)\|-\|\R_{\bar{x}}^{-1}(x)\| \le \varepsilon \|\log_{\bar{x}}(x)\|,
    \end{equation*}
    as $\hat{x}=\log_{\bar{x}}(x)$, $\hat{\bar{x}}=0$. We conclude with %
    $\distM(x, \bar{x})=\|\hat{x} - \hat{\bar{x}}\| = \|\log_{\bar{x}}(x)\|$.
\end{proof}

\begin{proposition}\label{prop:tangretraction}
    Consider a $p$-dimensional $\C^k$-submanifold $\M$ of $\bbR^n$ around a point $\bar{x}\in\M$. The mapping $\R : \tangentBundle\to\M$, defined for $(x, \eta)\in\tangentBundle$ near $(\bar{x}, 0)$ by $\proj_x(\R(x, \eta)) = \eta$ defines a second-order retraction near $(\bar{x}, 0)$. The point-wise retraction, defined as $\R_x = \R(x, \cdot)$, is locally invertible with inverse $\R_{x}^{-1}=\proj_{x}$.
\end{proposition}

\begin{proof}
    Let $\Psi : \bbR^n\to\bbR^{n-p}$ denote a $\C^k$ function defining $\M$ around $\bar{x}$: for all $x$ close enough to $\bar{x}$, there holds $x\in\M \Leftrightarrow \Psi(x)=0$, and $\D\Psi(x)$ is surjective. Consider the equation $\Phi(x, \eta_t, \eta_n) = 0$ around $(\bar{x}, 0, 0)$, with
    \begin{equation*}
        \begin{array}{rl}
            \Phi : \left\{ x, \eta_t, \eta_n : x\in\M, \eta_t\in\tangentM, \eta_n\in\normalM \right\} & \to \bbR                       \\
            x, \eta_t, \eta_n                                                                         & \mapsto \Psi(x+\eta_t+\eta_n).
        \end{array}
    \end{equation*}
    The partial differential $\D_{\eta_n}\Phi(\bar{x}, 0, 0)$ is, for $\xi_n\in\normalM[\bar{x}]$,
    \begin{equation*}
        \D_{\eta_n}\Phi(\bar{x}, 0, 0)[\xi_n] = \D\Psi(\bar{x})[\xi_n].
    \end{equation*}
    Since $\bar{x}\in\M$, $\D_{\eta_n}\Phi(\bar{x}, 0, 0)$ is surjective from $\normalM[\bar{x}]$ to $\bbR^{n-p}$ so its a bijection. The implicit function theorem provides the existence of neighborhoods $\N_{\bar{x}}^1\subset\M$, $\N_{0}^2\subset\cup_{x\in\M} \tangentM$, $\N_{0}^3\subset\cup_{x\in\M}\normalM$ and a unique $\C^k$ function $\eta_n : \N_{\bar{x}}^1 \times \N_0^2 \to \N_0^3$ such that, for all $x\in\N_{\bar{x}}^1$, $\eta_t\in\N_0^2$ and $\eta_n\in\N_0^3$, $\eta_n(\bar{x}, 0) = 0$ and
    \begin{equation*}
        \Phi(x, \eta_t, \eta_n(x, \eta_t)) = 0 \Leftrightarrow x+\eta_t+\eta_n(x, \eta_t) \in \M.
    \end{equation*}
    It also provides an expression for the partial derivative of $\eta_n$ at $(x, 0)$ along $\eta_t$: for $\xi_t\in\tangentM$,
    \begin{equation*}
        \D_{\eta_t} \eta_n(x, 0)[\xi_t] = - \left[ \D_{\eta_n}\Phi(x, 0, 0) \right]^{-1} \D_{\eta_t} \Phi(x, 0, 0)[\xi_t].
    \end{equation*}
    As noted before, $\D_{\eta_n}\Phi(x, 0, 0)$ is bijective since $x\in\M$. Besides, $\D_{\eta_t} \Phi(x, 0, 0) = \D\Phi(x)[\xi_t]=0$ since $\tangentM$ identifies as the kernel of $\D\Phi(x)$. Thus $\D_{\eta_t} \eta_n(x, 0) = 0$.

    Now, define a map $\R:\N_{\bar{x}}^1\times\N_0^2 \to \M$ by $\R(x, \eta_t) = x + \eta_t + \eta_n(x, \eta_t)$. This map has degree of smoothness $\C^k$ since $\eta_n$ is $\C^k$, satisfies $\R(x, 0) = x$ since $\eta_n(x, 0)=0$ and satisfies $\D_{\eta_t}\eta_n(x, 0) = I + \D_{\eta_t}(x, 0) = I$. Thus $\R$ defines a retraction on a neighborhood of $(\bar{x}, 0)$.

    We turn to show the second-order property of $\R$. Consider the smooth curve $\smoothcurve$ defined as $c(t) = \R(x, t\eta)$ for some $x\in\N_{\bar{x}}^1$, $\eta_t\in\tangentM\cap\N_0^2$. It's first derivative writes
    \begin{equation*}
        c'(t) = \eta + \D_{\eta_t}\eta_n(x, t\eta)[\eta] = \eta.
    \end{equation*}
    The acceleration of the curve $c$ is obtained by computing the derivative of $c'(\cdot)$ in the ambient space and then projecting onto $\tangentM$. Thus $c''(t)=0$ and in particular, $c''(0)=0$ which makes $\R$ a second-order retraction.
\end{proof}

\begin{lemma}\label{lemma:Euclidean_to_Riemannian}
    Consider a point $\bar{x}$ of a Riemannian manifold $\M$. For any $\varepsilon>0$, there exists a neighborhood $\U$ of $\bar{x}$ in $\M$ such that, for all $x\in\U$,
    \begin{equation*}
        (1-\varepsilon)\distM(x, \bar{x}) \le \|x-\bar{x}\| \le (1+\varepsilon)\distM(x, \bar{x}),
    \end{equation*}
    where $\|x-\bar{x}\|$ is the Euclidean distance in the ambient space.
\end{lemma}

\begin{proof}
    Let $\bar{x}$, $x$ denote two close points on $\M$. Consider the tangential retraction introduced in \cref{prop:tangretraction}. As a retraction, it satisfies:
    \begin{equation*}
        \R_{\bar{x}}(\eta) = \R_{\bar{x}}(0) + \D\R_{\bar{x}}(0)[\eta] + \mathcal O(\|\eta\|^2) = \bar{x} + \mathcal O(\|\eta\|^2).
    \end{equation*}
    Taking $x=\R_{\bar{x}}(\eta)$ allows to write $x = \bar{x} + \mathcal O(\|\R_{\bar{x}}^{-1}(x)\|^2)$, so that for any small $\varepsilon_1>0$, there exists a small enough neighborhood $\U_1\subset\U$ of $\bar{x}$ in $\M$ such that
    \begin{equation*}
        (1-\varepsilon_1) \|\R_{\bar{x}}^{-1}(x)\| \le \|x-\bar{x}\| \le (1+\varepsilon_1)\|\R_{\bar{x}}^{-1}(x)\|.
    \end{equation*}
    By \cref{lem:InvRetractionApproxLog}, for $\varepsilon_2>0$ small enough, there exists a neighborhood $\U_2\subset\U$ of $\bar{x}$ such that,
    \begin{equation*}
        (1-\varepsilon_2)\distM(x, \bar{x}) \le \|\R^{-1}_{\bar{x}}(x)\| \le (1+\varepsilon_2)\distM(x, \bar{x}).
    \end{equation*}
    With $\varepsilon_1$, $\varepsilon_2$ such that $1-\varepsilon=(1-\varepsilon_1)(1-\varepsilon_2)$, we combine the two estimates to conclude.%
\end{proof}

\begin{theorem}[Soundness of the Riemannian \revise{line search}]\label{th:unitstepsuperlinearcv}
    Consider a manifold $\M$ equipped with a retraction $\R$ and a twice differentiable function $\funman:\M\to\RR$ that admits a strong local minimizer $x^\star$, that is, a point such that $\Hess \funman(x^\star)$ is positive definite. If $x$ is close to $x^\star$, $\eta$ brings a superlinear improvement towards $x^\star$, that is $\distM(\R_x(\eta), x^\star) = o(\distM(x, x^\star))$ as $x\to x^\star$, and $0<m_1<1/2$, then $\eta$ is acceptable by the Armijo rule\;\eqref{eq:Armijo} with unit stepsize $\alpha=1$.
\end{theorem}

\begin{proof}

    Let $x, \eta\in\tangentBundle$ denote a pair such that $x$ is close to $x^\star$ and $\distM(\R_x(\eta), x^\star) = o(\distM(x, x^\star))$. For convenience, let $x_+ = \R_x(\eta)$ denote the next point.

    Following \cite{absil2009optimization} (see e.g. the proof of Th. 6.3.2), we work in local coordinates around $x^\star$, representing any point $x\in\M$ by $\widehat{x} = \log_{x^\star}(x)$ and any tangent vector $\eta\in\tangentM$ by $\widehat{\eta}_x = \D \log_{x^\star}(x)[\eta]$. The function $\funman$ is represented by $\widehat{\funman} = \funman\circ\exp_{x^\star}:\tangentM[x^\star]\to\bbR$. Defining the coordinates via the logarithm grants the useful property that the Riemannian distance of any two points $x, y\in\M$ matches the euclidean distance between their representatives: $\distM(x, y) = \|\widehat{x}-\widehat{y}\|$. Besides, there holds
    \begin{equation}\label{eq:gradHess_to_localcoords}
        \D \funman(x)[\eta]=\D \widehat{\funman}(\widehat{x})[\widehat{\eta}] \quad \text{ and } \quad \Hess \funman(x)[\eta, \eta]=\D \widehat{\funman}(\widehat{x})[\widehat{\eta}, \widehat{\eta}].
    \end{equation}
    Indeed, $\D \funman(x)[\eta] = (\funman\circ\geocurve)'(0)$ and $\Hess \funman(x)[\eta, \eta] = (\funman\circ\geocurve)''(0)$, where $\geocurve$ denotes the geodesic curve defined by $\widehat{\geocurve}(t) = \widehat{x} + t\widehat{\eta}$. Using $\funman\circ\geocurve=\widehat{\funman}\circ\widehat{\geocurve}$, one obtains the result.

    \underline{Step 1.} We derive an approximation of $\D \funman(x)[\eta] = \langle \grad \funman(x), \eta\rangle$ in terms of $\D^2 \widehat{\funman}(\widehat{x^\star})[\widehat{x}-\widehat{x^\star}]^2$. To do so, we go through the intermediate quantity $\D \widehat{\funman}(\widehat{x}) [\widehat{x_+}-\widehat{x}]$, and handle precisely the $o(\cdot)$ terms. By smoothness of $\widehat{\funman}$ and since $\D \widehat{\funman}(\widehat{x^\star})=0$, Taylor's formula for $\D \widehat{\funman}$ writes
    \begin{align*}
        \D \widehat{\funman}(\widehat{x}) [\widehat{x_+}-\widehat{x}] &= \D^2 \widehat{\funman}(\widehat{x^\star})[\widehat{x_+}-\widehat{x}, \widehat{x}-\widehat{x^\star}] + o(\|\widehat{x}-\widehat{x^\star}\|^2)\\
        &= -\D^2 \widehat{\funman}(\widehat{x^\star})[\widehat{x}-\widehat{x^\star}]^2 + \D^2 \widehat{\funman}(\widehat{x^\star})[\widehat{x_+}-\widehat{x^\star}, \widehat{x}-\widehat{x^\star}] + o(\|\widehat{x}-\widehat{x^\star}\|^2)\\
        &= -\D^2 \widehat{\funman}(\widehat{x^\star})[\widehat{x}-\widehat{x^\star}]^2 + o(\|\widehat{x}-\widehat{x^\star}\|^2),
    \end{align*}
    where, in the last step, we used that $\|\widehat{x_+}-\widehat{x^\star}\| = o(\|\widehat{x}-\widehat{x^\star}\|)$ to get that $\|\D^2 \widehat{\funman}(\widehat{x^\star})[\widehat{x_+}-\widehat{x^\star}, \widehat{x}-\widehat{x^\star}]\| = \|\D^2 \widehat{\funman}(\widehat{x^\star})\| \|\widehat{x_+}-\widehat{x^\star}\|\|\widehat{x}-\widehat{x^\star}\| = o(\|\widehat{x}-\widehat{x^\star}\|^2)$.
    We now turn to show that $\D \widehat{\funman}(\widehat{x}) [\widehat{x_+}-\widehat{x}]$ behaves as $\D \funman(x)[\eta]$ up to $o(\|\widehat{x_+}-\widehat{x}\|^2)$. Since $\D \funman(x)[\eta]=\D\widehat{\funman}(\widehat{x})[\widehat{\eta}]$ by \eqref{eq:gradHess_to_localcoords}, there holds:
    \begin{equation*}
        \|\D \funman(x)[\eta] - \D\widehat{\funman}(\widehat{x})[\widehat{x_+} - \widehat{x}]\| = \|\D\widehat{\funman}(\widehat{x})[\widehat{\eta} - (\widehat{x_+} - \widehat{x})]\| \le \|\D\widehat{\funman}(\widehat{x}) \| \|\widehat{\eta} - (\widehat{x_+} - \widehat{x})\|.
    \end{equation*}

    As $\funman$ is twice differentiable and $\exp$ is $\C^\infty$, $\widehat{\funman}$ is twice differentiable as well. In particular its derivative is locally Lipschitz continuous, so that for $\widehat{x}$ near $\widehat{x^\star}$, we obtain a first estimate:
    \begin{equation*}
        \|\D\widehat{\funman}(\widehat{x})\| = \|\D\widehat{\funman}(\widehat{x}) - \D\widehat{\funman}(\widehat{x^\star})\| = \mathcal O (\| \widehat{x}-\widehat{x^\star} \|).
    \end{equation*}

    Besides, the following estimate holds $\|\widehat{\eta} - (\widehat{x_+} - \widehat{x})\| = o (\| \widehat{x}-\widehat{x^\star} \|)$. Indeed, as the function $\log_{x^\star}\circ\R_x : \tangentM\to\tangentM[x^\star]$ is differentiable, there holds for $\eta\in\tangentM$ small,
    \begin{equation*}
        \log_{x^\star}(\R_x(\eta)) = \log_{x^\star}(\R_x(0)) + \D\log_{x^\star}(\R_x(0))[\D\R_x(0)[\eta]] + o(\|\eta\|),
    \end{equation*}
    which simplifies to $\widehat{x_+} = \widehat{x} + \widehat{\eta} + o(\|\eta\|)$. \Cref{lem:InvRetractionApproxLog} allows to write $\|\eta\| = \|\R_x^{-1}(x_+)\| = \mathcal O(\distM(x, x_+))$. Using the triangular inequality and the assumption that $\distM(x_+, x^\star) = o(\distM(x, x^*))$ we get
    \begin{equation*}
        \distM(x, x_+) \le \distM(x, x^\star) + \distM(x^\star, x_+) = \mathcal O(\distM(x, x^*)) = \mathcal O(\|\widehat{x}-\widehat{x^\star}\|),
    \end{equation*}
    so that the second estimate holds.

    Combining the two above estimates allows to conclude that
    \begin{equation*}
        \|\D \funman(x)[\eta] - \D\widehat{\funman}(\widehat{x})[\widehat{x_+} - \widehat{x}]\| = o(\|\widehat{x}-\widehat{x^\star}\|^2),
    \end{equation*}
    so that overall,
    \begin{equation*}
        \D \funman(x)[\eta] = \D \widehat{\funman}(\widehat{x}) [\widehat{x_+}-\widehat{x}] + o(\|\widehat{x}-\widehat{x^\star}\|^2) = -\D^2 \widehat{\funman}(\widehat{x^\star})[\widehat{x}-\widehat{x^\star}]^2 + o(\|\widehat{x}-\widehat{x^\star}\|^2).
    \end{equation*}



    Using that $\|\widehat{x}-\widehat{x^\star}\| = \distM(x, x^\star)$ and $\D^2 \widehat{\funman}(\widehat{x^\star}) = \Hess \funman(x^\star)$ \eqref{eq:gradHess_to_localcoords}, we obtain
    \begin{equation}\label{eq:proofunitstepsize_gradhess}
        \D \funman(x)[\eta] = -\Hess \funman(x^\star)[\widehat{x}-\widehat{x^\star}]^2 + o(\distM(x, x^\star)^2).
    \end{equation}

    \underline{Step 2.} The function $\funman$ admits a second-order development around $x^\star$: applying \cref{eq:manifoldSecondOrderDevSecRetraction} with the exponential map $\exp_{x^\star}$ as a second-order retraction yields
    \begin{equation}\label{eq:proofunitstepsize_fdev}
        \funman(x) = \funman(x^\star) + \frac{1}{2} \Hess \funman(x^\star)[\widehat{x}-\widehat{x^\star}]^2 + o(\distM(x, x^\star)^2),
    \end{equation}
    where we used that $\distM(x, x^\star) = \|\log_{x^\star}(x)-\log_{x^\star}(x^\star)\|$. Denote $0 < l \le L$ the lower and upper eigenvalues of $\Hess \funman(x^\star)$. The combination $\eqref{eq:proofunitstepsize_fdev} + m_1 \eqref{eq:proofunitstepsize_gradhess}$ writes
    \begin{align*}
        \funman(x) + m_1 \D \funman(x)[\eta] &= \funman(x^\star) + (\frac{1}{2}-m_1) \Hess \funman(x^\star)[\widehat{x}-\widehat{x^\star}]^2 + o(\distM(x, x^\star)^2) \\
        &\ge \funman(x^\star) + (\frac{1}{2}-m_1) l \distM(x, x^\star)^2 + o(\distM(x, x^\star)^2),
    \end{align*}

    Let $\varepsilon >0$ such that $\frac{1}{2}L \varepsilon^2  < (\frac{1}{2}-m_1) l$. As $\distM(x_+, x^\star)=o(\distM(x, x^\star))$, for $x$ close enough to $x^\star$ there holds $\distM(x_+, x^\star) \le \varepsilon \distM(x, x^\star)$. Combining this with the second-order development of $f$ at $x_+$, there holds:
    \begin{align*}
        \funman(x_+) &= \funman(x^\star) + \frac{1}{2} \Hess \funman(x^\star)[\widehat{x_+}-\widehat{x^\star}]^2 + o(\distM(x_+, x^\star)^2) \\
        &\le \funman(x^\star) + \frac{1}{2}L \distM(x_+, x^\star)^2 + o(\distM(x_+, x^\star)^2)\\
        &\le \funman(x^\star) + \frac{1}{2}L \varepsilon^2 \distM(x, x^\star)^2 + o(\distM(x, x^\star)^2).
    \end{align*}

    Subtracting the two estimates yields
    \begin{equation*}
        \funman(x_+) - (\funman(x) + m_1 \D \funman(x)[\eta]) \le \left(\frac{1}{2}L \varepsilon^2 - (\frac{1}{2}-m_1) l \right) \distM(x, x^\star)^2 + o(\distM(x, x^\star)^2),
    \end{equation*}
    which ensures that the Armijo condition is satisfied.





\end{proof}

