    \end{algorithmic}
\end{algorithm}

\begin{algorithm}
    \caption{$\manupdate$-Newton\label{alg:ManUpNewton}}
    \begin{algorithmic}[1]
        \Require Manifold $\M$, point $x\in\M$
        \State Find $d$ in $\tangentM$ that solves
        \begin{equation*}\tag{Newton equation}\label{eq:Newtoneq}
            \grad F(x) + \Hess F(x)[d] = 0
        \end{equation*}
        \State Find $\alpha$ satisfying the Armijo condition \eqref{eq:Armijo} with direction $d$
        \State \Return $y = R_x(\alpha d)$
    \end{algorithmic}
\end{algorithm}

Standing at point $x\in\M$ with a proposed direction $\eta\in\tangentM$, a stepsize $\alpha>0$ is \emph{acceptable} \revise{if} it satisfies the following \emph{Armijo} condition %
\begin{equation}\label{eq:Armijo}
    \funtot(\R_x(\alpha \eta)) \le \funtot(x) + m_1 \alpha \langle \grad \funtot(x), \eta\rangle, \qquad\text{for $0 < m_1 < 1/2$.}
\end{equation}

\noindent\textbf{Algorithms on manifolds: retractions and convergence rates.}
Iterative Riemannian methods require a way to produce curves on $\M$ given a point $x$ and a tangent vector $\eta$. A geodesic curve passing at $(x, \eta)$, while attractive as the generalization of the straight line, has a prohibitive computational cost. We thus \emph{retractions}, i.e. approximations of it, defined on a manifold $\M$ as a smooth map $\R : \tangentBundle \to \M$ such that
\[%
    \text{$\R_x (0) = x\quad$ and $\quad \D\R_x (0) : \tangentM \to\tangentM$ is the identity map: $D\R_x (0 )[v] = v$,}
\]%
where, for each $x \in\M$, $\R_x : \tangentM\to\M$ is defined as the restriction of $\R$ at $x$, so that $\R_x(v) = \R(x, v)$. A \emph{second-order retraction} is a retraction $\R$ such that, for all $(x, \eta)\in\tangentBundle$, the curve $c(t)=\R_x(t\eta)$ has zero acceleration at 0: $c''(0)=0$.
Thus $t\mapsto\R_x(t\eta)$ is a practical curve passing by $(x, \eta)$ at $0$, and provides a similar development as above: %
for $t$ near 0,
\begin{equation}\label{eq:manifoldSecondOrderDevSecRetraction}
    \funman\circ\R_x(t \eta) = \funman(x) + t \langle \grad \funman(x), \eta\rangle + \frac{t^2}{2}\langle \Hess \funman(x)[\eta], \eta\rangle + o(t^2 \|\eta\|^2).
\end{equation}

Finally, the convergence rates on manifolds are defined as follows. A sequence of points $(x_k)$ \emph{converges (Q-)linearly} to some point $\bar{x}\in\M$ if there exist an integer $K>0$ and a constant $q\in(0,1)$ such that, for all $k\ge K$, there holds
\begin{equation*}
    \distM(x_{k+1}, \bar{x})\le q~ \distM(x_{k}, \bar{x}).
\end{equation*}
The sequence \emph{converges with order at least $p$} if there exists an integer $K>0$ and a constant $q\in(0,1)$ such that, for all $k\ge K$, there holds
\begin{equation*}
    \distM(x_{k+1}, \bar{x})\le q~\distM(x_{k}, \bar{x})^p.
\end{equation*}
The convergence is \emph{superlinear} when $p>1$ and \emph{quadratic} when $p=2$.

Consider a point $\bar{x}$ with $\funns(\bar{x})$ finite. The set of \emph{regular subgradients} %
\begin{equation*}
    \widehat\partial \funns(\bar{x}) \triangleq \left\{ v : \funns(x) \ge \funns(\bar{x}) + \langle v, x-\bar{x} \rangle + o(\|x-\bar{x}\|) \text{ for all } x\in\bbR^n \right\}
\end{equation*}
is closed and convex, but the subdifferential mapping $\widehat\partial \funns(\cdot)$ may not be outer semi-continuous \cite[Th. 8.6, Prop. 8.7]{rockafellar2009variational}. To overcome this problem, the set of \emph{(general or limiting) subgradients} is defined as
\begin{equation*}
    \partial \funns(\bar{x}) \triangleq \left\{ \lim_r v_r : v_r\in\widehat\partial \funns(x_r), x_r\to\bar{x}, \funns(x_r)\to \funns(\bar{x}) \right\}.
\end{equation*}
The limiting subdifferential is by design outer semi-continuous:
\[
\limsup_{x\to\bar{x}} \partial \funns (x) = \{u : \exists x_r\to\bar{x}, \exists u_r \to u \text{ with } u_r\in  \partial \funns (x_r) \} ~\subset~ \partial \funns (\bar{x}),
\]
which is an attractive property to study the properties of sequences of points whose subgradients converge.
We say that a function is \emph{(Clarke) regular} at $\bar{x}$ if the regular and limiting subdifferentials at $\bar{x}$ coincide \cite[Def. 7.25, Cor. 8.11]{rockafellar2009variational}. This is notably the case for convex functions where the two above definitions coincide with the convex subdifferential \cite[Prop. 8.12]{rockafellar2009variational}.

A central tool to tackle non-differentiable functions is the \emph{proximity operator}.
For\;$\gamma\!>\!0$ and a function $\funns$; it is defined as the set-valued mapping
\begin{equation*}
    \prox_{\gamma \funns}(y) \triangleq \argmin_{u\in\bbR^n} \left\{ \funns(u) + \frac{1}{2\gamma}\|u-y\|^2\right\}.
\end{equation*}

\begin{definition}[partial smoothness]
    A function $g$ is ($\C^2$-)\emph{partly smooth} at a point $\bar{x}$ relative to a set $\M$ containing $\bar{x}$ if $\M$ is a $\C^2$ manifold around $\bar{x}$ and:
    \begin{itemize}
        \item (smoothness) the restriction of $g$ to $\M$ is a $\C^2$ function near $\bar{x}$;
        \item (regularity) $g$ is (Clarke) regular at all points $x\in\M$ near $\bar{x}$, with $\partial g(x)\neq\emptyset$;
        \item (sharpness) the affine span of $\partial g(\bar{x})$ is a translate of $\normalM[\bar{x}]$;
        \item (sub-continuity) the set-valued mapping $\partial g$ restricted to $\M$ is continuous at $\bar{x}$.
    \end{itemize}
\end{definition}

\begin{definition}\label{def:structqual}
   A point $\bar{x}$ of a $C^2$ submanifold $\M$ is a $r$-\emph{structured critical} point for $(f,g)$~if we have:
    \begin{itemize}
