        \item[ii)] qualification condition: $0 \in \ri (\nabla f + \partial g)(\bar{x})$;
        \item[iii)] prox-regularity: $g$ is $r$-prox-regular at $\bar{x}$;
        \item[iv)] partial smoothness: $g$ is partly-smooth at $\bar{x}$ with respect to $\M$.
    \end{itemize}
\end{definition}

