\begin{lemma}\label{lemma:prox_strong_min}
    Let $f$ and $g$ denote two functions and $\bar{x}$, $\bar{y}$ two points such that $f$ is differentiable at $\bar{y}$ and $g$ is $r$-prox-regular at $\bar{x}$ for subgradient $\frac{1}{\gamma}(\bar{y}-\bar{x}) - \nabla f(\bar{y}) \in \partial g(\bar{x})$ with $\gamma \in (0, 1/r)$.
    Then, the function $\rho_{\bar{y}} : x\mapsto g(x) + \frac{1}{2\gamma}\|\bar{y}-\gamma\nabla f(\bar{y}) - x\|^2$ satisfies %
    \begin{equation*}
        \rho_{\bar{y}}(x) \ge \rho_{\bar{y}}(\bar{x}) + \frac{1}{2} \left( \frac{1}{\gamma} - r \right) \| x-\bar{x} \|^2, \qquad \text{for all $x$ near $\bar{x}$.}
    \end{equation*}
\end{lemma}

\begin{proof}
    Prox-regularity of $g$ at $\bar{x}$ with subgradient $\frac{1}{\gamma} (\bar{y}-\gamma \nabla f(\bar{y}) - \bar{x}) \in \partial g(\bar{x})$ writes
    \begin{equation*}
        g(x) \ge g(\bar{x}) + \frac{1}{\gamma}\langle \bar{y}-\gamma \nabla f(\bar{y}) - \bar{x} , x-\bar{x} \rangle - \frac{r}{2} \| x-\bar{x} \|^2.
    \end{equation*}
    The identity $ 2\langle b-a, c-a\rangle = \|b-a\|^2 + \|c-a\|^2 -   \|b-c\|^2 $ applied to the previous scalar product yields:
    \begin{equation*}
        g(x) \ge g(\bar{x}) + \frac{1}{2\gamma} \| \bar{y}-\gamma \nabla f(\bar{y}) - \bar{x} \|^2 + \frac{1}{2\gamma} \| x-\bar{x} \|^2 - \frac{1}{2\gamma} \|\bar{y}-\gamma \nabla f(\bar{y}) - x \|^2 - \frac{r}{2} \| x-\bar{x} \|^2,
    \end{equation*}
    which rewrites
    \begin{equation*}
        \underbrace{ g(x) + \frac{1}{2\gamma} \|\bar{y}-\gamma \nabla f(\bar{y}) - x \|^2 }_{=\rho_{\bar{y}}(x) } \ge  \underbrace{  g(\bar{x}) + \frac{1}{2\gamma} \| \bar{y}-\gamma \nabla f(\bar{y}) - \bar{x} \|^2   }_{=\rho_{\bar{y}}(\bar{x}) } + \frac{1}{2} \left( \frac{1}{\gamma} - r \right) \| x-\bar{x} \|^2,
    \end{equation*}
    \vspace*{-1ex}
which is the claimed inequality.
\end{proof}

